function sortedAccounts(rows){return [...rows].sort((a,b)=>Number(needsRevision(b))-Number(needsRevision(a))||a.name.localeCompare(b.name)||a.id.localeCompare(b.id))}
function sortedContacts(rows){return [...rows].sort((a,b)=>Number(contactNeedsRevision(b,contactIssues.get(b.id)||[],duplicates.get(b.id)||[]))-Number(contactNeedsRevision(a,contactIssues.get(a.id)||[],duplicates.get(a.id)||[]))||(a.first_name+' '+a.last_name).localeCompare(b.first_name+' '+b.last_name)||a.id.localeCompare(b.id))}
function inContactView(c,v){if(c.status==='incorrect')return false;return v==='revision'?contactNeedsRevision(c,contactIssues.get(c.id)||[],duplicates.get(c.id)||[]):true}
// Possible duplicates: contacts at one organisation sharing a phone, an email or a name. A key starts with a letter
// for the reason and holds its first contact's id; a list is made only when a second contact shares it.
const duplicateReasons={P:'Phone',E:'Email',N:'Same name at organisation'};
function scan(){indexCompleteness();duplicates.clear();const groups=new Map(),add=(key,id)=>{const seen=groups.get(key);if(seen===undefined)groups.set(key,id);else if(Array.isArray(seen))seen.push(id);else groups.set(key,[seen,id]);};for(const c of contacts){if(c.status==='incorrect')continue;const phone=(c.country_code+c.phone).replace(/\D/g,'');if(phone.length>=7)add('P'+c.organization_id+':'+phone,c.id);if(c.email)add('E'+c.organization_id+':'+c.email.trim().toLowerCase(),c.id);const name=normalize(c.first_name+c.last_name);if(name.length>=3)add('N'+c.organization_id+':'+name,c.id);}for(const [key,ids] of groups)if(Array.isArray(ids))for(const id of ids){const list=duplicates.get(id)||[];list.push({reason:duplicateReasons[key[0]],ids:ids.filter(x=>x!==id)});duplicates.set(id,list)}for(const c of contacts)if(duplicates.has(c.id)&&c.status==='kept'&&!(contactIssues.get(c.id)||[]).length)accountReviewCounts.set(c.organization_id,(accountReviewCounts.get(c.organization_id)||0)+1);rollupReviewCounts()}
function render(){if(!me)return;if(view==='dashboard'&&me.role==='staff'){view='personal';if(typeof personalSection!=='undefined')personalSection='task';}syncWorkspaceNavigation();if(typeof accessBlocked==='function'&&accessBlocked())return;if(view!=='dashboard'&&!listsLoaded){message('Loading your workspace…');return (listsLoading||loadLists()).then(()=>{message('');return render()},e=>message(friendlyError(e),true))}if(view==='accounting')return accountingWorkspace();else if(view==='dashboard')return dashboardWorkspace();else if(view==='personal')return personalWorkspace();else if(view==='review')return reviewQueue();else if(view==='inventory')return inventoryWorkspace();else if(view==='sales')return salesDeliveryWorkspace();else if(view==='leads')return leadsWorkspace();else if(view==='pending')return pendingStockWorkspace();else if(view==='purchasing')return purchasingWorkspace();else if(view==='tallyinvoices')return tallyInvoicesWorkspace();else if(view==='stockcount')return stockCountWorkspace();else if(view==='reports')return reportsWorkspace();else if(view==='travel')return travelWorkspace();else if(view==='requests')return customerRequestsWorkspace();else if(view==='settings')return settingsWorkspace();else if(view==='service')return serviceWorkspace();else if(view==='recycle')return renderRecycleBin();else if(view==='staff')return staff();else if(view==='approvals')return projectApprovals();else if(view==='checklist')return checklist();else if(view==='guide')return guide();else return profileView()}
function reviewQueue(){
 const rows=contactReviewQueue(contacts,organizations,duplicates),q=search.trim().toLowerCase(),matches=rows.filter(({contact,organization,reasons})=>`${contact.first_name||''} ${contact.last_name||''} ${organization.name||''} ${organization.location||''} ${reasons.join(' ')}`.toLowerCase().includes(q));
 const pages=Math.max(1,Math.ceil(matches.length/30));page=Math.min(Math.max(page,0),pages-1);
 $('#content').innerHTML=`<section class="client-pages"><div class="heading"><div><small>CONTACT TASKS</small><h1>Fix contacts</h1><p class="muted">Start at the top. Edit the details, mark the contact complete, or delete it if it is no longer needed.</p></div><button id="refresh">Refresh list</button></div><div class="help-strip"><strong>Yellow means action is needed.</strong><span>Incomplete, unchecked, and possible duplicate contacts all appear in this one list.</span></div>${recordsLockedNote()}<label class="directory-search"><span>Search this list</span><input id="reviewSearch" type="search" value="${esc(search)}" placeholder="Type a person, client, branch, or missing detail"></label><p class="count">${matches.length} shown · ${rows.length} contacts need revision</p>${matches.slice(page*30,page*30+30).map(({contact,organization,reasons})=>`<article class="contact incomplete"><div class="heading"><div><h2>${esc([contact.title,contact.first_name,contact.last_name].filter(Boolean).join(' ')||'Unnamed contact')}</h2><p class="contact-account">${esc(organization.name||'Client missing')} · ${esc(organization.location||'Location missing')}</p></div><span class="tag warn">Needs revision</span></div><ul class="review-reasons">${reasons.map(reason=>`<li>${esc(reason)}</li>`).join('')}</ul><div class="actions contact-actions">${canEditRecords()?`<button class="primary-action" data-edit="${esc(contact.id)}">Edit contact</button>`:''}<a class="button secondary-action" href="#/branch/${esc(contact.organization_id)}">View branch</a>${canEditRecords()?`<button class="danger" data-delete-contact="${esc(contact.id)}">Delete contact</button>`:''}</div></article>`).join('')||'<div class="empty"><strong>Nothing to fix here.</strong><br>No contacts match this search, or every active contact is complete.</div>'}${profilePagination(matches.length,pages,'contacts needing revision')}</section>`;
 $('#reviewSearch').oninput=event=>{search=event.target.value;page=0;renderSearchPreservingPosition(event.target,reviewQueue,150)};
}
function groupKey(name){const words=String(name||'').toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim().split(/\s+/);return words.length>=2?words.slice(0,2).join(' '):''}
function groupSuggestions(o){const key=groupKey(o.name);return key.length>=5?organizations.filter(x=>x.id!==o.id&&!x.parent_id&&groupKey(x.name)===key&&!organizations.some(y=>y.parent_id===x.id)).slice(0,12):[]}
function accountGrouping(o){
 const root=rootAccount(o),branches=sortedAccounts(childrenByParent.get(root.id)||[]),suggestions=groupSuggestions(root);
 return `<section class="group-panel"><div class="heading"><h3>${branches.length} branches</h3>${canEditRecords()?`<button data-link-parent="${root.id}">+ Link existing branch</button>`:''}</div>${branches.length?`<div class="branch-list"><button data-org="${root.id}" class="${root.id===o.id?'active':''}">All branches & contacts</button>${branches.map(x=>`<button data-org="${x.id}" class="${x.id===o.id?'active':''} ${needsRevision(x)?'incomplete':''}"><strong>${esc(x.name)}</strong><small>${esc(x.location||'Location missing')} · ${esc(x.type)}</small>${needsRevision(x)?'<span class="revision-label">Needs revision</span>':''}</button>`).join('')}</div>`:'<p class="muted">No branches linked yet. Contacts are listed directly under this account.</p>'}${canEditRecords()&&suggestions.length?`<details><summary>${suggestions.length} suggested branches · review and approve</summary>${suggestions.map(x=>`<div class="suggested-branch"><span>${esc(x.name)}<small>${esc(x.location||'Location missing')} · ${esc(x.type)}</small></span><button data-group="${x.id}" data-parent="${root.id}">Review branch</button></div>`).join('')}</details>`:''}</section>`;
}
async function linkBranch(id,parentId=selected){const o=organizations.find(x=>x.id===parentId),branch=organizations.find(x=>x.id===id);if(!o||!branch)throw Error('Choose an existing account.');const r=await client.rpc('set_organization_parent',{p_id:id,p_parent_id:o.id});if(r.error)throw r.error;invalidateLocalApproval(branch.parent_id);branch.parent_id=o.id;invalidateLocalApproval(o.id);scan();render();message('Branch group saved.');}
async function editProduct(id){if(!canEditRecords())throw Error(recordsLockedText);const p=products.find(x=>x.id===id);if(!p)return;const name=prompt('Product name',p.name);if(name===null)return;if(!name.trim())throw Error('Product name is required.');const sku=prompt('Stock code (optional)',p.sku);if(sku===null)return;const r=await client.rpc('save_product',{p_id:id,p_revision:p.revision,p_name:name.trim(),p_sku:sku.trim()});if(r.error)throw r.error;products[products.findIndex(x=>x.id===id)]=Array.isArray(r.data)?r.data[0]:r.data;inventory();message('Product changes saved.');}
function contactView(){
 const q=search.toLowerCase(),orgs=sortedAccounts(organizations.filter(o=>!o.parent_id&&[...familyIds(o)].some(id=>{const x=orgIndex.get(id);return (x.name+' '+x.location+' '+x.type).toLowerCase().includes(q)}))),o=organizations.find(x=>x.id===selected),root=rootAccount(o),scope=familyIds(o),rootScope=familyIds(root);
 const accountContacts=contacts.filter(c=>scope.has(c.organization_id)),list=sortedContacts(accountContacts.filter(c=>inContactView(c,filter)));
 const issues=accountIssues.get(root?.id)||[],revisionCount=accountReviewCounts.get(selected)||0;
 $('#content').innerHTML=`<div class="heading"><div><small>CLIENT DIRECTORY</small><h1>Client profiles</h1><p class="muted">Account → contacts. Red profiles need revision and appear first.</p></div><div class="actions">${canEditRecords()?'<button id="newOrg">+ Account</button>':''}${me.role==='owner'?'<button data-view="staff">Staff & import</button>':''}<button id="refresh">Refresh</button></div></div><div class="workspace"><aside class="account-directory"><label><span>Find an account</span><input id="orgSearch" placeholder="Account, location or type" value="${esc(search)}"></label><p class="count">${orgs.length} accounts · ${orgs.filter(needsRevision).length} need revision</p><div class="orgs">${orgs.slice(0,100).map(x=>`<button class="org ${x.id===root?.id?'active':''} ${needsRevision(x)?'incomplete':''}" data-org="${x.id}" aria-pressed="${x.id===root?.id}"><strong>${esc(x.name||'Account name missing')}</strong><small>${esc(x.location||'Location missing')} · ${esc(x.type||'Type missing')}</small>${needsRevision(x)?`<span class="revision-label">Needs revision${accountReviewCounts.get(x.id)?' · '+accountReviewCounts.get(x.id)+' contacts':''}</span>`:''}</button>`).join('')||'<p>No accounts found.</p>'}</div><p class="count">Showing first 100 matches. Search to narrow the list.</p></aside><section>${o?`<div class="account-head ${issues.length?'incomplete':''}"><small>CLIENT PROFILE · ACCOUNT</small><h2>${esc(root.name||'Account name missing')}</h2><div class="profile-facts"><div><small>Location</small><strong>${esc(root.location||'Missing')}</strong></div><div><small>Organisation type</small><strong>${esc(root.type||'Missing')}</strong></div><div><small>Contacts under account</small><strong>${contacts.filter(c=>rootScope.has(c.organization_id)&&c.status!=='incorrect').length}</strong></div></div>${issues.length?`<p class="revision-label">Needs revision · ${issues.map(esc).join(', ')}</p>`:''}<div class="actions">${canEditRecords()?`<button data-edit-account="${root.id}">Edit account profile</button>`:''}</div></div>${accountGrouping(o)}<div class="profile-sections"><span class="current">Contacts</span>${['Active orders','Leads','Service','Customer history'].map(x=>`<span>${x}<small>Later feature</small></span>`).join('')}</div><div class="heading"><div><h2>${o.id===root.id?'Contacts across this account':esc(o.name)}</h2>${o.id!==root.id?`<p>${esc(o.location)} · ${esc(o.type)}</p><div class="actions">${canEditRecords()?`<button data-edit-account="${o.id}">Edit branch</button><button id="ungroupAccount">Remove branch from group</button>`:''}</div>`:''}<p class="muted">${revisionCount} need revision · email is optional</p>${recordsLockedNote()}</div>${canEditRecords()?'<button id="newContact">+ Contact</button>':''}</div>`:'<div class="empty">Import or add your first account.</div>'}<div class="tabs">${[['all','All contacts'],['revision','Needs fixing']].map(([v,t])=>`<button data-filter="${v}" class="${v===filter?'active':''}">${t} <small>${accountContacts.filter(c=>inContactView(c,v)).length}</small></button>`).join('')}</div>${list.slice(page*30,page*30+30).map(card).join('')||'<div class="empty">No contacts in this view.</div>'}<div class="actions"><button id="prev" ${page===0?'disabled':''}>Previous</button><span>${list.length} records · page ${page+1}</span><button id="next" ${(page+1)*30>=list.length?'disabled':''}>Next</button></div></section></div>`;
 $('#orgSearch').oninput=e=>{search=e.target.value;page=0;renderSearchPreservingPosition(e.target,contactView,150)};
}
function card(c){const missing=contactIssues.get(c.id)||[],hits=duplicates.get(c.id)||[],revision=contactNeedsRevision(c,missing,hits),targets=[...new Set(hits.flatMap(h=>h.ids))],quality=typeof contactQuality==='function'?contactQuality(missing,hits):{level:'',issues:[]};return `<article class="contact ${hits.length?'duplicate':''} ${revision?'incomplete':''} ${quality.level?'quality-'+quality.level:''}"><div class="heading"><h3>${c.title&&c.title!=='N/A'?esc(c.title)+' ':''}${esc(c.first_name)} ${esc(c.last_name)}</h3>${typeof qualityBadge==='function'?qualityBadge(quality.level,quality.issues):''}<span class="tag ${revision?'warn':''}">${revision?'Needs revision':'Complete'}</span></div><p class="contact-account">${esc(orgIndex.get(c.organization_id)?.name||'Account missing')}</p>${missing.length?`<p class="revision-label">Needs revision · ${missing.map(esc).join(', ')}</p>`:''}${hits.length?`<span class="tag warn">Possible duplicate · ${[...new Set(hits.map(h=>h.reason))].map(esc).join(', ')}</span><details><summary>Compare ${targets.length} matching record(s)</summary>${targets.slice(0,20).map(id=>{const t=contacts.find(x=>x.id===id),o=organizations.find(x=>x.id===t.organization_id);return `<p>${esc(t.first_name+' '+t.last_name)} · ${esc(o?.name)} · ${esc(t.country_code+t.phone)} <button data-goto="${t.organization_id}">Open organisation</button></p>`}).join('')}</details>`:''}<div class="details"><div><small>Position</small>${esc(c.position||'Missing')}</div><div><small>Phone</small>${esc(c.country_code)} ${esc(c.phone||'Missing')}</div><div><small>Email · optional</small>${esc(c.email||'—')}</div></div><div class="actions contact-actions">${canEditRecords()?`<button class="primary-action" data-edit="${c.id}">Edit contact</button>${revision?`<button data-keep="${c.id}">Mark complete ✓</button>`:''}`:''}${canEditRecords()?`<button class="danger" data-delete-contact="${c.id}">Delete contact</button>`:''}</div></article>`}
async function edit(c){
 editing={...c};const contactRoot=rootAccount(orgIndex.get(c.organization_id)||orgIndex.get(selected));
 const branchOptions=[...familyIds(contactRoot)].map(id=>orgIndex.get(id)).filter(o=>!(childrenByParent.get(o.id)?.length)||o.id===c.organization_id);
 $('#editForm').noValidate=true;
 $('#fields').innerHTML=`<p class="muted">All fields except email are required. Names must start with a capital letter. Original incomplete imports stay available for revision.</p><label><span>Account / branch</span><select name="organization_id" required><option value="">Choose branch</option>${branchOptions.map(o=>`<option value="${o.id}" ${o.id===c.organization_id?'selected':''}>${esc(o.name)} · ${esc(o.location)}</option>`).join('')}</select></label><div class="grid"><label><span>Title</span><select name="title" required><option value="">Choose title</option>${['Doctor','Mr.','Mrs.','N/A'].map(t=>`<option ${t===c.title?'selected':''}>${t}</option>`).join('')}</select></label>${field('first_name','First name',c.first_name,'text',true)}${field('last_name','Last name',c.last_name,'text',true)}${field('position','Position / role',c.position,'text',true)}<label><span>Country</span><select name="phone_country" required><option value="">Choose country</option>${countryOptions(c.phone_country)}</select></label>${field('country_code','Calling code',c.country_code,'text',true)}${field('phone','National phone number',c.phone,'tel',true)}<p id="phoneHint" class="muted"></p>${field('email','Email · optional',c.email,'email')}</div>`;
 const form=$('#editForm'),country=form.elements.namedItem('phone_country'),code=form.elements.namedItem('country_code');code.readOnly=true;
 const hint=()=>{$('#phoneHint').textContent=phoneLengthMessage(country.value);};country.onchange=()=>{code.value=window.PHONE_RULES[country.value]?'+'+window.PHONE_RULES[country.value].code:'';hint()};hint();
 $('#formError').textContent='';$('#editor').showModal();
 if(c.revision){const r=await client.from('contacts').select('source').eq('id',c.id).single();if(editing?.id===c.id&&$('#editor').open&&r.data?.source){const box=document.createElement('details');box.innerHTML='<summary>Original source record · read only</summary><pre class=source>'+esc(JSON.stringify(r.data.source,null,2))+'</pre>';$('#fields').append(box)}}
}
function validate(c){
 const errors=(c.revision===0||c.status!=='incorrect')?contactFieldErrors(c):{};
 if(c.revision===0||c.status!=='incorrect'){const issues=missingAccount(orgIndex.get(c.organization_id));if(issues.length)errors.organization_id='Complete the branch profile first: '+issues.join(', ');}
 if(c.status==='incorrect'&&!c.reason?.trim())errors.reason='Give a reason for flagging this record.';
 if(Object.keys(errors).length){const e=Error('Field invalid. Correct the highlighted fields.');e.fields=errors;throw e}return c;
}
async function save(c){validate(c);const r=await client.rpc('save_contact',{p_id:c.id,p_revision:c.revision||0,p_values:Object.fromEntries(['organization_id','title','first_name','last_name','position','phone_country','country_code','phone','email','status','reason'].map(k=>[k,c[k]??'']))});if(r.error)throw r.error;const value=Array.isArray(r.data)?r.data[0]:r.data;const i=contacts.findIndex(x=>x.id===c.id);if(i<0)contacts.push(value);else contacts[i]=value;invalidateLocalApproval(c.organization_id);scan();render();message('Contact saved.');return value}
function inventory(){const q=search.toLowerCase(),rows=products.filter(p=>!p.deleted_at).filter(p=>(p.name+' '+p.sku).toLowerCase().includes(q));$('#content').innerHTML=`<div class="heading"><div><small>PRODUCT CLEANUP</small><h1>Inventory</h1><p class="muted">Review the source product list. Confirm matches without merging or changing stock.</p>${recordsLockedNote()}</div><div class="actions">${canEditRecords()?'<button id="newProduct">+ Add product</button>':''}<button id="refresh">Refresh</button></div></div><div class="toolbar"><input id="productSearch" aria-label="Search products" placeholder="Find a product or stock code" value="${esc(search)}"><span>${rows.length} products</span></div><div class="card table-wrap"><table><thead><tr><th>Product</th><th>Stock code</th><th>Matching</th><th>Review</th></tr></thead><tbody>${rows.slice(page*50,page*50+50).map(p=>{const candidates=products.filter(x=>x.id!==p.id&&normalize(x.name)===normalize(p.name));const target=products.find(x=>x.id===p.match_id);return `<tr class="${candidates.length&&p.match_status!=='confirmed'?'duplicate':''}"><td>${esc(p.name)}<small>${p.source?.origin==='manual'?'Added manually':`${esc(p.source?.source_file||'')} · row ${esc(p.source?.source_row||'')}`}</small><details><summary>Original product details</summary><pre class="source">${esc(JSON.stringify(p.source?.raw||{},null,2))}</pre></details></td><td>${esc(p.sku||'Not supplied')}</td><td>${esc(p.match_status)}${target?`<small>Linked to ${esc(target.name)} · ${esc(target.sku||target.id.slice(0,8))}</small>`:''}${candidates.length?`<small>${candidates.length} exact-name candidate(s)—check before matching</small>`:''}</td><td>${canEditRecords()?`<button data-product-edit="${p.id}">Edit product</button><button data-match="${p.id}">Review match</button>`:'<small class="muted">View only</small>'}</td></tr>`}).join('')}</tbody></table>${rows.length?'':'<div class="empty">No products found. An owner can add a product or import the prepared list.</div>'}<div class="actions"><button id="prev" ${page===0?'disabled':''}>Previous</button><span>Page ${page+1}</span><button id="next" ${(page+1)*50>=rows.length?'disabled':''}>Next</button></div></div>`;$('#productSearch').oninput=e=>{search=e.target.value;page=0;renderSearchPreservingPosition(e.target,inventory)}}
async function addProduct(){
 if(!canEditRecords())throw Error(recordsLockedText);
 const enteredName=prompt('Product name (required)');if(enteredName===null)return;
 const name=enteredName.trim();if(!name)throw Error('Enter a product name.');
 const enteredSku=prompt('Stock code (optional)');if(enteredSku===null)return;
 const r=await client.rpc('add_product',{p_id:crypto.randomUUID(),p_name:name,p_sku:enteredSku.trim(),p_source:{origin:'manual'}});
 if(r.error)throw r.error;
 search='';page=0;await load();message('Product saved.');
}
async function staff(){if(me.role==='head'&&typeof headStaffPage==='function')return headStaffPage();if(me.role!=='owner'){view='contacts';return render()}$('#content').innerHTML=`<h1>Staff</h1><section class="card"><h2>Staff logins</h2><button type="button" id="addEmployee">Add employee</button> <button type="button" id="addEmployeeList">Add employees from a list</button> <button type="button" id="employeeNameEditor">Set employee name</button><p class="muted">Add employee gives the person a login made from their name and a temporary password. They choose their own password the first time they sign in.</p><details><summary>Turn a login on or off by email</summary><form id="staffForm">${field('email','Staff email address','','email',true)}<label><span>Role</span><select name="role"><option value="staff">Staff</option><option value="head">Department head</option><option value="owner">Owner</option></select></label><label><span>Access</span><select name="active"><option value="true">Active</option><option value="false">Disabled</option></select></label><button type="submit">Save staff access</button></form></details><div id="staffList"></div></section><details class="card"><summary>One-time data import</summary><p class="muted">Only used when the system is first set up. Records already in the system are not duplicated.</p><label><span>Clients, contacts and products file</span><input id="import" type="file" accept="application/json"></label><p id="importStatus"></p><label><span>Setup checklist file</span><input id="checklistImport" type="file" accept="application/json"></label></details>`;$('#employeeNameEditor').onclick=openEmployeeNameEditor;$('#addEmployee').onclick=()=>run(async()=>openStaffOnboarding());$('#addEmployeeList').onclick=()=>run(async()=>openStaffListImport());const r=await client.from('staff').select('user_id,role,active,phone,department,access');if(r.error)throw r.error;$('#staffList').innerHTML=staffListHtml(r.data);bindStaffList(r.data);if(typeof decorateStaffTwoStep==='function')decorateStaffTwoStep().catch(()=>{});if(typeof decorateStaffAccounting==='function')decorateStaffAccounting().catch(()=>{});if(typeof renderWorkStepOwners==='function')renderWorkStepOwners($('#staffList').closest('section')).catch(()=>{});$('#checklistImport').onchange=e=>run(async()=>{const rows=JSON.parse(await e.target.files[0].text());const result=await client.rpc('import_checklist',{p_rows:rows});if(result.error)throw result.error;message('Checklist loaded.');});$('#staffForm').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);const r=await client.rpc('manage_staff_email',{p_email:f.get('email'),p_role:f.get('role'),p_active:f.get('active')==='true'});if(r.error)throw r.error;await staff();message('Staff membership saved.')})};$('#import').onchange=e=>run(async()=>{const d=JSON.parse(await e.target.files[0].text());if(!Array.isArray(d.organizations)||!Array.isArray(d.contacts)||!Array.isArray(d.products))throw Error('Choose the prepared import file.');if(!confirm(`Import ${d.organizations.length} organisations, ${d.contacts.length} contacts and ${d.products.length} products into this private workspace?`))return;for(const kind of ['organizations','contacts','products'])for(let i=0;i<d[kind].length;i+=250){$('#importStatus').textContent=`Importing ${kind}: ${i} / ${d[kind].length}`;const r=await client.rpc('import_records',{['p_'+kind]:d[kind].slice(i,i+250)});if(r.error)throw Error(`Import stopped at ${kind} row ${i}. Completed batches are safe to retry. ${r.error.message}`)}await load();message('Import complete.');})}
// Every server request gets a time limit, so a lost connection shows a message instead of leaving the app stuck
// "working" with every button ignored. Uploads and downloads of files get longer.
function requestTimeLimit(url){return /\/storage\/v1\//.test(String(url))?180000:45000}
function timedFetch(url,options={}){
 const limit=AbortSignal.timeout(requestTimeLimit(url));
 const signal=options.signal&&AbortSignal.any?AbortSignal.any([options.signal,limit]):options.signal||limit;
 // A stopped request reads as "Connection problem: …" wherever a page shows the error.
 return fetch(url,{...options,signal}).catch(error=>{
  if(options.signal?.aborted&&!limit.aborted)throw error;
  const plain=new Error('the server did not answer. Check your connection and press Refresh.');plain.name='Connection problem';throw plain;
 });
}
function friendlyError(e){
 const text=String(e?.message||'');
 if(e?.name==='TimeoutError'||e?.name==='AbortError'||/Connection problem|signal timed out|aborted|Failed to fetch|NetworkError|Load failed/i.test(text))return 'The connection is slow or offline. Nothing more was saved. Check your connection and try again.';
 return text||'Something went wrong. Please retry.';
}
async function run(fn){if(busy)return;busy=true;try{await fn()}catch(e){message(friendlyError(e),true)}finally{busy=false;replayQueuedNavigation()}}
// The menu item pressed while the last action was still running (workspace-navigation.js), pressed again now.
function replayQueuedNavigation(){const button=typeof navWhileBusy!=='undefined'?navWhileBusy:null;if(!button)return;navWhileBusy=null;if(button.isConnected&&!button.hidden)button.click()}
$('#editForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{showFieldErrors(e.target,{});const values=Object.fromEntries(new FormData(e.target));await save({...editing,...values});$('#editor').close()}catch(err){$('#formError').textContent=err.message;showFieldErrors(e.target,err.fields||{})}finally{busy=false}};
$('#closeEditor').onclick=()=>$('#editor').close();
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||busy)return;
 if(b.dataset.view){view=b.dataset.view;search='';page=0;if(view==='contacts')return goProfile('clients');return run(async()=>render())}
 if(b.dataset.org||b.dataset.goto)return goProfile(b.dataset.goto?'branch':'client',b.dataset.org||b.dataset.goto);
 if(b.dataset.filter){filter=b.dataset.filter;page=0;return render()}
 if(b.id==='prev'||b.id==='next'){page+=b.id==='prev'?-1:1;return render()}
 if(b.dataset.deleteOrg)return run(()=>openDeleteRecord('organization',b.dataset.deleteOrg));
 if(b.dataset.deleteContact)return run(()=>openDeleteRecord('contact',b.dataset.deleteContact));
 // Clients & items data (migration 071): the database refuses these saves too; this explains it before a form opens.
 if((b.dataset.edit||b.id==='newContact'||b.dataset.keep||b.dataset.restore||b.dataset.incorrect||b.dataset.productEdit||b.dataset.match)&&!canEditRecords())return message(recordsLockedText,true);
 if(b.dataset.edit)return run(()=>edit(contacts.find(x=>x.id===b.dataset.edit)));
 if(b.id==='newContact')return edit({id:crypto.randomUUID(),organization_id:selected,status:'review',revision:0});
 if(b.id==='newOrg')return openOrganizationForm();
 if(b.dataset.editAccount)return openOrganizationForm(orgIndex.get(b.dataset.editAccount));
 if(b.id==='newProduct')return openProductForm();
 if(b.dataset.productEdit)return openProductForm(products.find(x=>x.id===b.dataset.productEdit));
 if(b.dataset.incorrect)return openIncorrectForm(contacts.find(x=>x.id===b.dataset.incorrect));
 if(b.dataset.match)return openMatchForm(products.find(x=>x.id===b.dataset.match));
 if(b.dataset.group)return openBranchForm(orgIndex.get(b.dataset.parent),orgIndex.get(b.dataset.group));
 if(b.dataset.linkParent)return openBranchForm(orgIndex.get(b.dataset.linkParent));
 run(async()=>{
 if(b.id==='logout'){await client.auth.signOut();login()}
 else if(b.id==='refresh'){inventoryLoaded=false;await load();}
 else if(b.dataset.approveOrg){const r=await client.rpc('approve_organization',{p_id:b.dataset.approveOrg});if(r.error)throw r.error;const row=Array.isArray(r.data)?r.data[0]:r.data;Object.assign(orgIndex.get(row.id),row);render();message('Client profile approved.');}
 else if(b.dataset.keep)await save({...contacts.find(x=>x.id===b.dataset.keep),status:'kept'});
 else if(b.dataset.restore){const c=contacts.find(x=>x.id===b.dataset.restore),r=await client.rpc('restore_contact',{p_id:c.id,p_revision:c.revision});if(r.error)throw r.error;const value=Array.isArray(r.data)?r.data[0]:r.data;contacts[contacts.findIndex(x=>x.id===c.id)]=value;invalidateLocalApproval(c.organization_id);scan();render();message('Contact restored to review.');}
 else if(b.id==='ungroupAccount'){const r=await client.rpc('set_organization_parent',{p_id:selected,p_parent_id:null});if(r.error)throw r.error;invalidateLocalApproval(orgIndex.get(selected).parent_id);orgIndex.get(selected).parent_id=null;invalidateLocalApproval(selected);scan();render();message('Branch removed from group.');}
 });
});
(async()=>{const cfg=window.ERP_CONFIG;if(!cfg?.url||!cfg?.key)return setup();if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(cfg.url))return setup();client=supabase.createClient(cfg.url,cfg.key,{auth:{storage:sessionStorage,persistSession:true,autoRefreshToken:true,detectSessionInUrl:true},global:{fetch:timedFetch}});client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){clear();login()}});await run(load)})();

async function checklist(){
 const r=await client.from('feature_checklist').select('*').order('id');if(r.error)throw r.error;
 $('#content').innerHTML='<h1>ERP checklist</h1><section class="card"><h2>Current gate: client profiles</h2><p>Implemented: client → branch → contacts pages, required title and separate names, country phone validation, yellow revision queues, branch duplicate checks, and owner approval with automatic reset after edits.</p><p>Still required: review missing source information and accept the client workflow. The inventory format review now uses only PRODUCT LIST AND ALLOCATION.xlsx. Stock quantities and movements are not supplied in that workbook.</p></section><p class="muted">Finish and accept Feature 1 before starting the next workflow. Implemented, verified and accepted are different stages.</p>'+['feature-1','later'].map(phase=>'<section class="card"><h2>'+ (phase==='feature-1'?'Feature 1 · Sorting workspace':'Later · One workflow at a time')+'</h2>'+r.data.filter(x=>x.phase===phase).map(x=>`<article class="contact"><small>${esc(x.id)}</small><h3>${esc(x.title)}</h3><p>${esc(x.notes)}</p>${me.role==='owner'?`<label><span>Progress</span><select data-checklist="${esc(x.id)}" data-revision="${x.revision}">${['pending','implemented','verified','accepted'].map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`).join('')}</select></label>`:`<span class="tag">${esc(x.status)}</span>`}</article>`).join('')+'</section>').join('');
 document.querySelectorAll('[data-checklist]').forEach(el=>el.onchange=()=>run(async()=>{const row=r.data.find(x=>x.id===el.dataset.checklist);const out=await client.rpc('save_checklist',{p_id:row.id,p_revision:row.revision,p_status:el.value,p_notes:row.notes});if(out.error){el.value=row.status;throw out.error}await checklist();message('Checklist progress saved.')}));
}
;// admin-records.js
'use strict';
// Products: Clients & items data access (migration 071). Draft Pro formas: owner only.
function canArchiveBusiness(kind){return kind==='product'?canEditRecords():me?.role==='owner'}
async function openArchiveBusinessRecord(kind,id){
 if(!['product','proforma'].includes(kind))throw Error('Unsupported record type.');
 if(!canArchiveBusiness(kind))throw Error(kind==='product'?recordsLockedText:'Owner access is required.');
 const record=kind==='product'?products.find(p=>p.id===id):salesProforma(id);
 if(!record||record.deleted_at)throw Error('Record changed. Refresh before deleting.');
 if(kind==='proforma'&&record.status!=='draft')throw Error('Only draft pro formas can be deleted.');
 const form=actionForm('Move to Deleted Items',`<p>Delete <strong>${esc(record.name||record.document_number)}</strong> from the active list?</p><p>You can restore it from Deleted Items. Linked history remains intact. No reason is required.</p>`,async()=>{
  if(!canArchiveBusiness(kind))throw Error('Access changed. Nothing was deleted.');
  const args={p_id:id,p_archived:true};if(kind==='proforma')args.p_expected_version=record.version;
  const result=await client.rpc(kind==='product'?'set_product_archived':'set_draft_proforma_archived',args);if(result.error)throw result.error;
  if(kind==='proforma'){await loadSalesDelivery();if(salesLoadError)throw Error(salesLoadError);salesEditing=null;render();}else await load();
  message('Moved to Deleted Items.');
 });
 const button=form?.querySelector('[type="submit"]');if(button)button.textContent='Delete';
}
async function appendDeletedBusinessRecords(request){
 const owner=me?.role==='owner';if(!canArchiveBusiness('product')&&!owner)return;
 const actor=me.user_id;
 const [productRows,proformaRows]=await Promise.all([canArchiveBusiness('product')?deletedRows('products','id,name,deleted_at'):null,owner?deletedRows('sales_proformas','id,document_number,version,deleted_at'):null]);
 if(request!==recycleRequest||view!=='recycle'||me?.user_id!==actor)return;
 const html=(kind,title,rows)=>`<section class="card"><h2>${title}</h2>${rows.map(row=>`<article class="recycle-record"><div><strong>${esc(row.name||row.document_number)}</strong><p>Deleted ${esc(recycleDate(row.deleted_at))}</p></div><button data-restore-business="${kind}" data-id="${esc(row.id)}" data-version="${row.version||0}">Restore</button></article>`).join('')||'<p>No deleted records.</p>'}</section>`;
 $('#content').insertAdjacentHTML('beforeend',(productRows?html('product','Products',productRows):'')+(proformaRows?html('proforma','Draft pro formas',proformaRows):''));
}
document.addEventListener('click',event=>{
 const button=event.target.closest('button');if(!button||busy)return;
 if(button.dataset.archiveBusiness)return run(()=>openArchiveBusinessRecord(button.dataset.archiveBusiness,button.dataset.id));
 if(button.dataset.restoreBusiness)return run(async()=>{
  const kind=button.dataset.restoreBusiness;if(!['product','proforma'].includes(kind))throw Error('Unsupported record type.');
  if(!canArchiveBusiness(kind))throw Error(kind==='product'?recordsLockedText:'Owner access is required.');
  const args={p_id:button.dataset.id,p_archived:false};if(kind==='proforma')args.p_expected_version=Number(button.dataset.version);
  const result=await client.rpc(kind==='product'?'set_product_archived':'set_draft_proforma_archived',args);if(result.error)throw result.error;
  await load();message('Record restored.');
 });
});
;// action-forms.js
'use strict';

const actionDialog=document.createElement('dialog');
actionDialog.id='actionEditor';
actionDialog.setAttribute('aria-labelledby','actionTitle');
const actionEditorForm=document.createElement('form');
actionEditorForm.innerHTML='<h2 id="actionTitle"></h2><div id="actionFields"></div><p id="actionError" class="error" role="alert"></p><div class="actions"><button type="submit">Save</button><button type="button" id="actionCancel">Cancel</button></div>';
actionDialog.append(actionEditorForm);
document.body.append(actionDialog);
let actionSubmit=null,actionSaving=false;
const actionFields=actionEditorForm.querySelector('#actionFields');
const actionError=actionEditorForm.querySelector('#actionError');
const actionSave=actionEditorForm.querySelector('[type="submit"]');
const actionCancel=actionEditorForm.querySelector('#actionCancel');
actionCancel.addEventListener('click',()=>{if(!actionSaving)actionDialog.close()});
actionDialog.addEventListener('cancel',e=>{if(actionSaving)e.preventDefault()});
actionDialog.addEventListener('close',()=>{actionSubmit=null});
actionEditorForm.addEventListener('submit',async e=>{
 e.preventDefault();if(actionSaving||!actionSubmit)return;
 const values=Object.fromEntries(new FormData(actionEditorForm));
 for(const key of Object.keys(values))if(typeof values[key]==='string')values[key]=values[key].trim();
 for(const control of actionFields.querySelectorAll('[required]'))if(!values[control.name]){actionError.textContent='Complete '+(control.labels?.[0]?.textContent.trim()||'the required field')+'.';control.focus();return;}
 actionSaving=true;actionSave.disabled=true;actionCancel.disabled=true;actionSave.textContent='Saving…';actionError.textContent='';
 try{await actionSubmit(values);actionDialog.close()}
 catch(error){actionError.textContent=error.message||'Could not save. Please retry.'}
 finally{actionSaving=false;actionSave.disabled=false;actionCancel.disabled=false;actionSave.textContent='Save'}
});

function actionForm(title,fields,onSubmit){
 if(actionSaving)return actionEditorForm;
 actionEditorForm.reset();actionEditorForm.querySelector('#actionTitle').textContent=title;
 actionFields.replaceChildren();
 if(typeof fields==='string')actionFields.innerHTML=fields;else actionFields.append(fields);
 actionError.textContent='';actionSubmit=onSubmit;
 if(!actionDialog.open)actionDialog.showModal();
 actionFields.querySelector('input,select,textarea')?.focus();
 return actionEditorForm;
}

function openOrganizationForm(o=null){
 if(!canEditRecords())throw Error(recordsLockedText);
 const id=o?.id||crypto.randomUUID();
 return actionForm(o?'Edit account':'Add account',
  field('name','Account name',o?.name||'','text',true)+field('location','Location',o?.location||'','text',true)+field('type','Organisation type',o?.type||'','text',true),
  async values=>{
   if(values.name!==titleCase(values.name)){showFieldErrors(actionEditorForm,{name:'Use Title Case, for example Shree Hindu Mandal.'});throw Error('Field invalid: account name must use Title Case.')}
   const r=await client.rpc('save_organization',{p_id:id,p_name:values.name,p_location:values.location,p_type:values.type});
   if(r.error)throw r.error;
   const row=Array.isArray(r.data)?r.data[0]:r.data;const index=organizations.findIndex(x=>x.id===id);if(index<0)organizations.push(row);else organizations[index]=row;selected=id;invalidateLocalApproval(id);scan();if(!o)goProfile('client',id);else render();message('Account saved.');
  });
}

function openProductForm(p=null){
 if(!canEditRecords())throw Error(recordsLockedText);
 const id=p?.id||crypto.randomUUID();
 return actionForm(p?'Edit product':'Add product',field('name','Product name',p?.name||'','text',true)+field('sku','Stock code · optional',p?.sku||''),async values=>{
  const r=p?await client.rpc('save_product',{p_id:id,p_revision:p.revision,p_name:values.name,p_sku:values.sku}):await client.rpc('add_product',{p_id:id,p_name:values.name,p_sku:values.sku,p_source:{origin:'manual'}});
  if(r.error)throw r.error;
  if(p){const row=Array.isArray(r.data)?r.data[0]:r.data;const index=products.findIndex(x=>x.id===id);if(index>=0)products[index]=row;render()}
  else{const saved=await client.from('products').select('*').eq('id',id).single();if(saved.error)throw saved.error;products.push(saved.data);search='';page=0;render()}
  message('Product saved.');
 });
}

function openIncorrectForm(c){
 if(!canEditRecords())throw Error(recordsLockedText);
 return actionForm('Flag contact as incorrect',`<p>${esc([c.first_name,c.last_name].filter(Boolean).join(' '))} will move to Incorrect for review. The record is retained.</p><label><span>Reason</span><textarea name="reason" required maxlength="2000">${esc(c.reason||'')}</textarea></label>`,async values=>save({...c,status:'incorrect',reason:values.reason}));
}

function openMatchForm(p){
 if(!canEditRecords())throw Error(recordsLockedText);
 const candidates=products.filter(x=>x.id!==p.id&&normalize(x.name)===normalize(p.name));
 const current=products.find(x=>x.id===p.match_id);
 const options=candidates.map(x=>`<option value="${esc(x.id)}" ${x.id===p.match_id?'selected':''}>${esc(x.name)} · ${esc(x.sku||'No stock code')} · ${esc(x.source?.source_file||'Manual entry')} ${esc(x.source?.source_row?'row '+x.source.source_row:'')} · ${esc(x.id.slice(0,8))}</option>`).join('');
 return actionForm('Review product match',`<p>Review the exact-name candidates for <strong>${esc(p.name)}</strong>. Saving a match keeps both records separate.</p>${current?`<p>Current match: ${esc(current.name)} · ${esc(current.sku||'No stock code')}</p>`:''}<label><span>Matching product</span><select name="match_id"><option value="">Clear match · leave unreviewed</option>${options}</select></label>${candidates.length?'':'<p class="muted">No exact-name candidates found. You can clear the current match.</p>'}`,async values=>{
  if(values.match_id&&!candidates.some(x=>x.id===values.match_id))throw Error('Choose a listed product.');
  const r=await client.rpc('set_product_match',{p_id:p.id,p_revision:p.revision,p_match_id:values.match_id||null,p_match_status:values.match_id?'confirmed':'unreviewed'});
  if(r.error)throw r.error;
  const row=Array.isArray(r.data)?r.data[0]:r.data;const index=products.findIndex(x=>x.id===p.id);if(index>=0)products[index]=row;
  render();message('Product match saved. No records merged.');
 });
}

function openBranchForm(parent,initialBranch=null){
 if(!canEditRecords())throw Error(recordsLockedText);
 if(!parent||parent.parent_id)throw Error('Choose a main account before linking a branch.');
 const parents=new Set(organizations.map(x=>x.parent_id).filter(Boolean));const eligible=organizations.filter(x=>x.id!==parent.id&&!x.parent_id&&!parents.has(x.id));
 const form=actionForm('Link existing branch',`<p>Main account: <strong>${esc(parent.name)}</strong> · ${esc(parent.location||'Location missing')}</p><label><span>Find a branch</span><input name="branch_search" type="search" placeholder="Account name, location or type"></label><label><span>Existing branch account</span><select name="branch_id" required></select></label><p id="branchRelationship" class="warning" aria-live="polite"></p><p class="muted">Check ownership and location before saving. Contacts and source records stay separate.</p>`,async values=>{
  if(!eligible.some(x=>x.id===values.branch_id))throw Error('Choose an eligible branch.');
  await linkBranch(values.branch_id,parent.id);
 });
 const searchInput=form.elements.namedItem('branch_search'),select=form.elements.namedItem('branch_id'),relationship=form.querySelector('#branchRelationship');
 const describe=()=>{const branch=eligible.find(x=>x.id===select.value);relationship.textContent=branch?`${branch.name} (${branch.location||'location missing'}) will become a branch under ${parent.name} (${parent.location||'location missing'}).`:'Choose the account to link as a branch.'};
 const populate=()=>{const previous=select.value||initialBranch?.id||'',q=searchInput.value.trim().toLowerCase(),rows=eligible.filter(x=>(x.name+' '+x.location+' '+x.type).toLowerCase().includes(q));select.replaceChildren(new Option(rows.length?'Choose an existing account':'No eligible accounts found',''));for(const x of rows)select.add(new Option(`${x.name} · ${x.location||'Location missing'} · ${x.type||'Type missing'}`,x.id));if(rows.some(x=>x.id===previous))select.value=previous;describe()};
 searchInput.addEventListener('input',populate);select.addEventListener('change',describe);populate();
 return form;
}
